package `in`.maitri.app

import android.content.Context
import org.json.JSONObject
import java.util.concurrent.ConcurrentHashMap

/**
 * App text translation. The English text is the key; app/src/main/assets/i18n/<code>.json holds each language
 * (generated by tools/i18n.py, machine-drafted, marked for review by native speakers). Placeholders are
 * positional, {0}, {1}…, so a translation can reorder them. Unknown text falls back to English.
 *
 * Screens 09–14 still use Android string resources; this covers the rest of the app, including messages built
 * outside Compose (network errors, notifications), which is why it isn't tied to a Context per call.
 */
object I18n {
    @Volatile private var app: Context? = null
    @Volatile private var code: String = "en"
    private val tables = ConcurrentHashMap<String, Map<String, String>>()

    /** Called at app start and whenever the language changes (the activity is recreated after that). */
    fun init(context: Context) {
        app = context.applicationContext
        code = `in`.maitri.app.ui.MaitriLocale.code(context.applicationContext)
    }

    fun language(): String = code

    /** Reads and parses the current language's table off the main thread (start-up), so the first tr() is cheap. */
    fun preload() { table(code) }

    internal fun table(code: String): Map<String, String> = tables.getOrPut(code) {
        val context = app ?: return@getOrPut emptyMap()
        runCatching {
            val json = JSONObject(context.assets.open("i18n/$code.json").bufferedReader().use { it.readText() })
            json.keys().asSequence().associateWith { json.getString(it) }
        }.getOrDefault(emptyMap())
    }

    internal fun format(template: String, args: Array<out Any?>): String =
        args.foldIndexed(template) { i, text, arg -> text.replace("{$i}", arg.toString()) }
}

/** Translates [en] into the app language; `{0}`… are replaced by [args]. */
fun tr(en: String, vararg args: Any?): String {
    val code = I18n.language()
    val text = if (code == "en") en else I18n.table(code)[en] ?: en
    return if (args.isEmpty()) text else I18n.format(text, args)
}

/** Marks English text that is translated later with tr(value), e.g. enum labels. Returns it unchanged. */
fun trKey(en: String): String = en
